// src/components/Home/HeroSection.jsx
function HeroSection({ onStartChat }) {
  return (
    <section className="bg-gradient-to-r from-blue-600 to-purple-700 text-white py-20">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
        <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold mb-6">
          Bienvenue sur notre site
        </h1>
        <p className="text-lg md:text-xl mb-8 max-w-2xl mx-auto leading-relaxed">
          Découvrez nos solutions innovantes pour transformer votre business digital.
        </p>
        <div className="flex items-center justify-center space-x-4">
          <button 
            onClick={onStartChat}
            className="bg-white text-blue-600 px-8 py-4 rounded-lg font-semibold hover:bg-gray-100 transition duration-300 shadow-lg hover:shadow-xl transform hover:-translate-y-1"
          >
            Démarrer maintenant
          </button>

        </div>
      </div>
    </section>
  );
}

export default HeroSection;
